import re,glob,os
MAP={'info':'neutral','success':'positive','warning':'caution'}
ATTR=re.compile(r'''\s*([^\s=/>]+)(?:\s*=\s*("[^"]*"|'[^']*'))?''')

def negate(e):
    e=e.strip()
    if e=='true': return 'false'
    if e=='false': return 'true'
    if e.startswith('!') and not e.startswith('!='):
        r=e[1:].strip()
        if r.startswith('(') and r.endswith(')'):
            d=0;ok=True
            for i,ch in enumerate(r):
                d+=ch=='('; d-=ch==')'
                if d==0 and i<len(r)-1: ok=False;break
            if ok: return r[1:-1].strip()
        return r
    if re.fullmatch(r"[\w$.?]+(\(\))?|[\w$.?]+\[[^\]]*\]",e): return '!'+e
    return '!('+e+')'

def tone_expr(e):
    e2=re.sub(r"(['\"])(info|success|warning)\1",lambda m:m.group(1)+MAP[m.group(2)]+m.group(1),e)
    return e2

def conv(s):
    """returns new s, needs_pipe"""
    out=[];i=0;pipe=False
    for m in re.finditer(r'<app-pill(?=[\s/>])',s):
        pass
    pos=0
    while True:
        m=re.compile(r'<app-pill(?=[\s/>])').search(s,pos)
        if not m: out.append(s[pos:]);break
        out.append(s[pos:m.start()])
        p=m.end();attrs=[]
        while True:
            w=re.compile(r'\s*').match(s,p);q=w.end()
            if s.startswith('/>',q): selfc=True;end=q+2;break
            if s[q]=='>': selfc=False;end=q+1;break
            a=ATTR.match(s,p);attrs.append((a.group(1),a.group(2)));p=a.end()
        inner=''
        if not selfc:
            c=s.index('</app-pill>',end)
            inner=s[end:c];assert inner.strip()=='',inner
            end=c+len('</app-pill>')
        new=[];content=''
        for n,v in attrs:
            val=v[1:-1] if v else None
            q=v[0] if v else '"'
            if n in('disableTooltip','[disableTooltip]'):
                assert n[0]=='[' and val is not None
                new.append('[tooltip]=%s%s%s'%(q,negate(val),q))
            elif n=='variant':
                new.append('tone=%s%s%s'%(q,MAP[val],q))
            elif n=='[variant]':
                if re.search(r"['\"]",val) and re.search(r"\?",val):
                    new.append('[tone]=%s%s%s'%(q,tone_expr(val),q))
                else:
                    new.append('[tone]=%s%s | pillTone%s'%(q,val,q));pipe=True
            elif n=='label': content=val
            elif n=='[label]': content='{{ %s }}'%val
            else: new.append(n+(('='+v) if v else ''))
        out.append('<app-pill'+''.join(' '+x for x in new)+'>'+content+'</app-pill>')
        pos=end
    return ''.join(out),pipe

for f in glob.glob('feature-*/*.html')+glob.glob('feature-*/*.ts'):
    s=open(f).read()
    if '<app-pill' not in s: continue
    if f.endswith('.html'):
        ns,pipe=conv(s)
        if ns!=s: open(f,'w').write(ns)
        ts=f[:-5]+'.ts'
    else:
        ns,pipe=conv(s)
        if ns!=s: open(f,'w').write(ns)
        ts=f
    if pipe:
        t=open(ts).read()
        if 'PillTonePipe' not in t:
            t=t.replace('import { PillComponent','import { PillTonePipe } from "../../lib/pill-tone.pipe";\nimport { PillComponent',1)
            t=t.replace('imports: [ PillComponent,','imports: [ PillComponent, PillTonePipe,',1)
            assert 'PillTonePipe,' in t
            open(ts,'w').write(t)

